examples:
TypeScript streaming resume example:
const client = new RedwoodClient({ apiKey: '...' })
const stream = client.chat.stream({ messages, resumeToken: savedToken })
stream.on('resumeToken', token => saveToken(token))
// SDK will attempt resume if connection drops and savedToken exists

Go resume usage:
cli := redwood.NewClient("TOKEN")
opts := redwood.StreamOptions{ResumeToken: lastToken}
str, err := cli.ChatStream(ctx, opts)
// library exposes helper redwood.NewIdempotencyKey() to generate consistent keys across retries
